CREATE VIEW v33674 AS SELECT x7.v33425, x7.v33425, 9999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999999 + 1 AS x4, MAX(x7.v33425 + 1) OVER (ORDER BY x7.v33425 DESC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS x5 FROM v33424 AS x7